-- Questões originais de estudo: Deitel e Deitel, Java: como programar, 10ª edição.
-- Tradução brasileira do PDF fornecido: Pearson Education do Brasil, 2017.
-- Contexto dos recursos: Java SE 8. Não são questões oficiais nem exercícios transcritos.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens entram como rascunhos. Revise antes de publicar.
-- Páginas são do arquivo PDF, não da numeração impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve registros existentes.
-- Capítulo 25: GUI do JavaFX: parte 1 — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('b31215fd-25a3-5296-a640-630858c5f23a', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Linguagem de Programação', 'Fácil', 'No JavaFX, Stage representa principalmente:', '["Um nó de texto apenas.","Uma janela de nível superior.","Uma conexão.","Um arquivo FXML.","Um botão."]'::jsonb, 1, 'O estágio hospeda uma cena.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 25, seção 25.3, páginas 901 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('77385a0d-0b53-558e-b9f0-add1f8dd5ede', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Linguagem de Programação', 'Fácil', 'Scene contém principalmente:', '["Uma transação JDBC.","Um arquivo de log.","Uma pilha de exceções.","Somente o método main.","O grafo de cena apresentado no estágio."]'::jsonb, 4, 'O grafo organiza nós da interface.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 25, seção 25.3, páginas 901 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('bc47b960-9ca7-5e93-a0f1-5b3e28b26dcc', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Linguagem de Programação', 'Fácil', 'Um nó do grafo JavaFX pode representar:', '["Um controle, layout ou elemento visual compatível.","Somente um primitivo.","Um pacote.","Um compilador.","Apenas um arquivo de dados."]'::jsonb, 0, 'A interface é organizada por relações de contenção entre nós.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 25, seção 25.3, páginas 901 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('429fabea-a3e1-5d73-8956-79c36556685e', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Linguagem de Programação', 'Médio', 'Scene Builder é usado principalmente para:', '["Gerenciar locks.","Executar consultas SQL.","Compilar toda a JVM.","Projetar visualmente interfaces JavaFX.","Serializar qualquer objeto Java."]'::jsonb, 3, 'Ele pode produzir a descrição FXML da interface.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 25, seção 25.2, páginas 901 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('54c20cbf-c526-528f-9930-4a06b0d6f8e2', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Linguagem de Programação', 'Médio', 'FXML descreve principalmente:', '["Uma thread.","Bytecode Java.","Um arquivo de conexão SQL.","A estrutura e propriedades de uma interface.","Uma árvore de busca binária obrigatória."]'::jsonb, 3, 'A marcação é carregada para criar objetos da interface.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 25, seção 25.4, páginas 902–906 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2645762f-40b9-55fb-b688-479ed8dea89b', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Linguagem de Programação', 'Médio', 'FXMLLoader tem como função:', '["Ordenar uma lista.","Confirmar uma transação.","Executar coleta de lixo.","Compilar apenas código C.","Carregar FXML e construir os objetos correspondentes."]'::jsonb, 4, 'O carregamento também pode associar um controlador.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 25, seção 25.5, páginas 907–918 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4c87a02b-e157-5ff1-89e4-56940e3bb179', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Linguagem de Programação', 'Médio', 'A classe controladora de uma interface FXML cuida normalmente de:', '["Comportamento e resposta às interações.","Toda compilação da linguagem.","Criação do sistema operacional.","Somente nomes de pacotes.","Serialização de cada pixel."]'::jsonb, 0, 'Separar estrutura visual e comportamento facilita organização.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 25, seção 25.5, páginas 907–918 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f1baadbc-b1d0-5a2f-9e6c-4adba9c3ca60', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Linguagem de Programação', 'Médio', 'A anotação @FXML pode marcar membros usados para:', '["Injeção ou acesso pelo carregador FXML.","Transformação em interface.","Sincronização automática.","Criação de transações.","Concessão de acesso público a qualquer classe."]'::jsonb, 0, 'A anotação tem função no vínculo entre FXML e controlador.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 25, seção 25.5, páginas 907–918 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f28711a8-0dfb-57ab-9cca-62e1a5cec41b', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Linguagem de Programação', 'Médio', 'O atributo fx:id ajuda a:', '["Ordenar automaticamente o grafo.","Criptografar o texto.","Identificar um nó para associação ao controlador.","Executar a JVM.","Confirmar o aplicativo."]'::jsonb, 2, 'O identificador precisa ser coerente com a associação pretendida.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 25, seção 25.5, páginas 907–918 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('540e92a1-26bc-5412-b636-f58b5b2013ab', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Linguagem de Programação', 'Médio', 'Um Button com ação registrada pode:', '["Invocar um tratador quando acionado.","Executar sempre uma consulta JDBC.","Criar automaticamente um novo Stage.","Mudar a classe do controlador.","Confirmar todos os valores."]'::jsonb, 0, 'Eventos conectam a interação ao comportamento programado.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 25, seção 25.5, páginas 907–918 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('16a12934-f46b-51d2-a2c4-e74d1a15ed80', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Linguagem de Programação', 'Médio', 'Um Label JavaFX é destinado principalmente a:', '["Tratar locks.","Exibir informação textual e conteúdo gráfico apropriado.","Executar comandos do sistema.","Receber parágrafos editáveis por padrão.","Armazenar uma fila."]'::jsonb, 1, 'É diferente de um campo de entrada textual.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 25, seção 25.4, páginas 902–906 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('972030df-1b4b-52a7-9e6a-4817d306c450', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Linguagem de Programação', 'Médio', 'TextField JavaFX é usado tipicamente para:', '["Desenho vetorial exclusivo.","Uma conexão de banco.","Armazenamento binário.","Exibição obrigatória de vídeo.","Entrada de texto em uma linha."]'::jsonb, 4, 'O controlador pode ler e validar o texto fornecido.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 25, seção 25.5, páginas 907–918 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('69449168-34a8-5cda-bfd3-94aaf243f3ef', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Linguagem de Programação', 'Médio', 'ImageView representa principalmente:', '["Uma thread.","Um analisador SQL.","Um banco relacional.","Um arquivo de classe.","Um nó para exibir uma imagem."]'::jsonb, 4, 'O objeto Image e sua visualização possuem papéis distintos.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 25, seção 25.4, páginas 902–906 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ed6a8208-6772-50a5-b355-b02c37eee9cc', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Linguagem de Programação', 'Médio', 'Preservar a proporção ao redimensionar uma imagem busca:', '["Garantir aumento de resolução.","Criar novos detalhes reais.","Eliminar o arquivo.","Evitar distorção da relação largura/altura.","Converter todo conteúdo em vetor."]'::jsonb, 3, 'Redimensionamento não recupera detalhes ausentes na imagem original.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 25, seção 25.4, páginas 902–906 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('593014ba-3a0f-5033-8450-6c547cad99d8', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Linguagem de Programação', 'Médio', 'VBox organiza seus filhos principalmente:', '["Em árvore binária de busca.","Verticalmente.","Por ordem de prioridade de threads.","Sempre sobrepostos.","Somente nas cinco regiões de BorderLayout."]'::jsonb, 1, 'O contêiner determina o arranjo visual dos nós.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 25, seção 25.4, páginas 902–906 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('682e4ed4-1fb4-5395-af88-16912b7bb1f8', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Linguagem de Programação', 'Médio', 'GridPane organiza os filhos em:', '["Um arquivo de texto.","Uma pilha de execução.","Somente uma fila horizontal.","Linhas e colunas.","Uma transação."]'::jsonb, 3, 'Restrições de grade determinam a posição dos nós.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 25, seção 25.5, páginas 907–918 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f177fbb7-e233-5e79-92a4-4dcf7e29adf0', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Linguagem de Programação', 'Médio', 'Um Slider JavaFX permite:', '["Executar somente um evento de teclado.","Criar uma tabela.","Selecionar um valor de um intervalo.","Escolher apenas arquivos.","Gerenciar threads."]'::jsonb, 2, 'O valor pode ser acompanhado por propriedades observáveis.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 25, seção 25.5, páginas 907–918 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('df298fed-30d3-55b4-8e95-fe692c939257', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Linguagem de Programação', 'Médio', 'Para reagir a mudanças de uma propriedade numérica de Slider, pode-se registrar:', '["Um ResultSet.","Um ChangeListener apropriado.","Um ObjectOutputStream.","Um compilador.","Um construtor JDBC."]'::jsonb, 1, 'O ouvinte acompanha mudanças do valor observado.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 25, seção 25.5, páginas 907–918 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('db39d84f-d25e-5cdc-a3b4-5da25eace798', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Linguagem de Programação', 'Médio', 'O método start de um aplicativo JavaFX recebe normalmente:', '["Um array de int.","Um Scanner obrigatório.","O Stage principal.","Uma SQLException.","Um ResultSet."]'::jsonb, 2, 'A subclasse de Application prepara e mostra a interface nesse ciclo.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 25, seção 25.5, páginas 907–918 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f2227d94-365d-5d9e-bd4e-064af6e4498f', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Linguagem de Programação', 'Médio', 'Qual cuidado mantém a interface coerente ao processar texto numérico informado?', '["Assumir que TextField já retorna double.","Ignorar qualquer exceção.","Converter e validar, tratando entradas inválidas.","Concatenar o texto e tratá-lo como soma numérica.","Mudar o tipo do controle para int."]'::jsonb, 2, 'Texto de entrada e valor numérico são representações distintas.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 25, seção 25.5, páginas 907–918 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
